insert into public.questions (id, title, prompt, output_columns, order_matters, points, hint_sql, hint_result)
values (2, $q$January 2025 breaks$q$, $q$List every break reported in January 2025, with the material of the main that broke.$q$, $q$break_id, reported_at, material — earliest report first$q$, true, 4,
$q$SELECT b.break_id, b.reported_at, m.material
FROM breaks AS b
JOIN mains AS m ON m.main_id = b.main_id
WHERE b.reported_at >= '2025-01-01'
  AND b.reported_at <  '2025-02-01'
ORDER BY b.reported_at;$q$,
$q${"columns": ["break_id", "reported_at", "material"], "rows": [[81, "2025-01-05T03:15:00", "Ductile Iron"], [83, "2025-01-08T00:15:00", "Cast Iron"], [82, "2025-01-08T17:45:00", "Asbestos Cement"], [84, "2025-01-09T09:15:00", "PVC"], [85, "2025-01-13T14:45:00", "Cast Iron"], [86, "2025-01-14T00:45:00", "Asbestos Cement"], [87, "2025-01-18T04:30:00", "Cast Iron"], [88, "2025-01-18T09:30:00", "Cast Iron"], [89, "2025-01-28T14:00:00", "Cast Iron"], [90, "2025-01-30T16:00:00", "Cast Iron"]]}$q$::jsonb)
