insert into public.questions (id, title, prompt, output_columns, order_matters, points, hint_sql, hint_result)
values (3, $q$Break rate per 100 miles$q$, $q$Utilities compare materials by breaks per 100 miles of pipe. For each material, count all breaks in the table and divide by that material's total miles of main (count every main, including ones that never broke), times 100. Round the rate to 1 decimal place.$q$, $q$material, breaks, breaks_per_100_miles — highest rate first$q$, true, 4,
$q$WITH break_counts AS (
    SELECT m.material, COUNT(*) AS breaks
    FROM breaks AS b
    JOIN mains AS m ON m.main_id = b.main_id
    GROUP BY m.material
),
pipe_miles AS (
    SELECT material, SUM(length_ft) / 5280.0 AS miles
    FROM mains
    GROUP BY material
)
SELECT p.material,
       COALESCE(c.breaks, 0) AS breaks,
       ROUND(COALESCE(c.breaks, 0) / p.miles * 100, 1) AS breaks_per_100_miles
FROM pipe_miles AS p
LEFT JOIN break_counts AS c ON c.material = p.material
ORDER BY breaks_per_100_miles DESC;$q$,
$q${"columns": ["material", "breaks", "breaks_per_100_miles"], "rows": [["Cast Iron", 74, 190.0], ["Asbestos Cement", 17, 77.8], ["Ductile Iron", 17, 48.4], ["PVC", 12, 33.1]]}$q$::jsonb)
