  points = excluded.points, hint_sql = excluded.hint_sql, hint_result = excluded.hint_result;
insert into public.questions (id, title, prompt, output_columns, order_matters, points, hint_sql, hint_result)
values (4, $q$Breaks still open$q$, $q$A break is still open if no crew has been assigned (it has no row in repairs) or the repair has started but completed_at is empty. List every open break and label it 'unassigned' or 'in progress'.$q$, $q$break_id, main_id, reported_at, status — oldest report first$q$, true, 4,
$q$SELECT b.break_id, b.main_id, b.reported_at,
       CASE WHEN r.repair_id IS NULL THEN 'unassigned'
            ELSE 'in progress' END AS status
FROM breaks AS b
LEFT JOIN repairs AS r ON r.break_id = b.break_id
WHERE r.completed_at IS NULL
ORDER BY b.reported_at;$q$,
$q${"columns": ["break_id", "main_id", "reported_at", "status"], "rows": [[37, 108, "2023-12-15T19:45:00", "unassigned"], [113, 147, "2025-12-01T02:30:00", "in progress"], [115, 243, "2025-12-11T01:45:00", "unassigned"], [117, 220, "2025-12-20T07:45:00", "in progress"], [118, 162, "2025-12-25T14:00:00", "unassigned"], [119, 121, "2025-12-29T04:15:00", "in progress"], [120, 202, "2025-12-31T05:15:00", "unassigned"]]}$q$::jsonb)
