insert into public.questions (id, title, prompt, output_columns, order_matters, points, hint_sql, hint_result)
values (5, $q$Fastest crews$q$, $q$For each crew, find the average hours from started_at to completed_at across its completed repairs. Only include crews with at least 20 completed repairs. Round hours to 1 decimal place.$q$, $q$crew_name, repairs, avg_hours — fastest first$q$, true, 4,
$q$SELECT c.crew_name,
       COUNT(*) AS repairs,
       ROUND(AVG(EXTRACT(EPOCH FROM r.completed_at - r.started_at) / 3600)::numeric, 1) AS avg_hours
FROM repairs AS r
JOIN crews AS c ON c.crew_id = r.crew_id
WHERE r.completed_at IS NOT NULL
GROUP BY c.crew_name
HAVING COUNT(*) >= 20
ORDER BY avg_hours;$q$,
$q${"columns": ["crew_name", "repairs", "avg_hours"], "rows": [["Crew B", 31, 8.1], ["Crew A", 31, 8.6], ["Crew C", 33, 8.9]]}$q$::jsonb)
